static inline uint32_t _sec_to_ms(uint32_t sec)
{
    if (sec == UINT32_MAX) {
        /* infinite stays infinite */
        return UINT32_MAX;
    }
    else if (sec > ((UINT32_MAX - 1) / MS_PER_SEC)) {
        /* truncate long intervals to largest possible value */
        return UINT32_MAX - 1;
    }
    else {
        return sec * MS_PER_SEC;
    }
}


