uint32_t one_at_a_time_hash(const uint8_t *buf, size_t len)
{
    uint32_t hash = 786431; /* prime */

    for (size_t i = 0; i < len; i++) {
        hash += buf[i];
        hash += hash << 10;
        hash ^= hash >> 6;
    }
    hash += hash << 3;
    hash ^= hash >> 11;
    hash += hash << 15;
    return hash;
}



