// Module code (from sys/net/application_layer/unicoap/options.c, similarity=0.53)
static size_t _encode_variable_uint(uint32_t* value)
{
    uint8_t* dest = (uint8_t*)value;
    size_t size = 0;

    /* count number of used bytes */
    uint32_t tmp = *value;
    while (tmp) {
        size += 1;
        tmp >>= 8;
    }

    /* convert to network byte order */
    tmp = htonl(*value);

    /* copy bytewise, starting with first actually used byte */
    *value = 0;
    uint8_t* cursor = (uint8_t*)&tmp;
    cursor += (sizeof(uint32_t) - size);
    for (unsigned n = 0; n < size; n++) {
        *dest = *cursor;
        dest += 1;
        cursor += 1;
    }

    return size;
}



